<?php
declare(strict_types=1);
require_once __DIR__ . '/_bootstrap.php';
require_once __DIR__ . '/../config/os_module.php';
require_once __DIR__ . '/../config/os_batch_billing.php';
require_once __DIR__ . '/../config/os_fiscal_queue.php';
require_once __DIR__ . '/_os_ui.php';

$pdo=os_db();$companyId=os_company_id();$userId=(int)(os_user_id()?:0);
os_require_enabled($pdo,$companyId);os_ensure_defaults($pdo,$companyId);
$schemaOk=os_batch_schema_ok($pdo);
$creDueDefault=date('Y-m-d',strtotime('+30 days'));
try{if(function_exists('finance_settings')&&function_exists('finance_cre_due_dates')){$creSet=finance_settings($pdo,$companyId);$creDates=finance_cre_due_dates($creSet,1,date('Y-m-d'));if(!empty($creDates[0]))$creDueDefault=$creDates[0];}}catch(Throwable $e){}
$error='';$ok=trim((string)($_GET['ok']??''));
$billedStatus=null;if($schemaOk){try{$billedStatus=os_batch_billed_status($pdo,$companyId);}catch(Throwable $e){$error=$e->getMessage();}}

function osbf_date_br($v):string{if(!$v)return'—';$t=strtotime((string)$v);return$t?date('d/m/Y',$t):'—';}
function osbf_invoice_no($v):string{return str_pad((string)(int)$v,6,'0',STR_PAD_LEFT);}
function osbf_pedido_no(PDO $pdo,int $companyId,int $pedidoId):string{if($pedidoId<=0)return'—';try{$st=$pdo->prepare('SELECT * FROM pedidos WHERE company_id=? AND id=? LIMIT 1');$st->execute([$companyId,$pedidoId]);$r=$st->fetch(PDO::FETCH_ASSOC);if($r&&function_exists('company_sequence_display'))return(string)company_sequence_display($r,'pedidos');}catch(Throwable $e){}return(string)$pedidoId;}
function osbf_redirect(string $url,string $ok='',string $err=''):never{$q=[];if($ok!=='')$q['ok']=$ok;if($err!=='')$q['err']=$err;$sep=str_contains($url,'?')?'&':'?';header('Location: '.$url.($q?$sep.http_build_query($q):''));exit;}

if($_SERVER['REQUEST_METHOD']==='POST'){
    try{
        os_batch_require_schema($pdo);os_batch_csrf_check((string)($_POST['csrf']??''));$action=(string)($_POST['action']??'');
        if($action==='create'){
            $invoiceId=os_batch_create_invoice($pdo,$companyId,$userId,(int)($_POST['person_id']??0),(int)($_POST['status_id']??0),(string)($_POST['period_start']??''),(string)($_POST['period_end']??''),(array)($_POST['order_ids']??[]),(string)($_POST['notes']??''));
            osbf_redirect('os_faturas.php?id='.$invoiceId,'Fatura de O.S. gerada para conferência. Nenhum lançamento financeiro foi criado nesta etapa.');
        }
        $invoiceId=(int)($_POST['invoice_id']??0);if($invoiceId<=0)throw new RuntimeException('Fatura inválida.');
        if(in_array($action,['approve','reopen','cancel'],true)){
            os_batch_set_status($pdo,$companyId,$invoiceId,$userId,$action);
            $msg=$action==='approve'?'Fatura aprovada. O faturamento consolidado já pode ser realizado.':($action==='reopen'?'Fatura devolvida para conferência.':'Fatura cancelada; as O.S. podem ser incluídas em outra fatura.');
            osbf_redirect('os_faturas.php?id='.$invoiceId,$msg);
        }
        if($action==='bill'){
            $pedidoId=os_batch_finalize_invoice($pdo,$companyId,$invoiceId,$userId,(int)($_POST['payment_method_id']??0),os_batch_date($_POST['due_date']??''));
            $pedidoNo=osbf_pedido_no($pdo,$companyId,$pedidoId);// A conferência fiscal será feita dentro do Pedido Detalhado, sem outro pedido.
            osbf_redirect('gestao_pedido_detalhado.php?os_nfse_lote='.$invoiceId);
        }
        throw new RuntimeException('Ação não reconhecida.');
    }catch(Throwable $e){$error=$e->getMessage();}
}
if($error===''&&!empty($_GET['err']))$error=trim((string)$_GET['err']);

$invoiceId=max(0,(int)($_GET['id']??0));$invoice=null;$invoiceOrders=[];$invoiceLines=[];$paymentMethods=[];$pedidoDisplay='—';
if($schemaOk&&$invoiceId>0){
    $invoice=os_batch_invoice($pdo,$companyId,$invoiceId);if(!$invoice){http_response_code(404);die('Fatura de O.S. não encontrada.');}
    $invoiceOrders=os_batch_invoice_orders($pdo,$companyId,$invoiceId);$invoiceLines=os_batch_invoice_lines($pdo,$companyId,$invoiceId);if((int)($invoice['pedido_id']??0)>0)$pedidoDisplay=osbf_pedido_no($pdo,$companyId,(int)$invoice['pedido_id']);
    $batchNfseDoc=null;
    if(strtoupper((string)($invoice['status']??''))==='FATURADA' && (int)($invoice['pedido_id']??0)>0){
      try{$bs=$pdo->prepare("SELECT d.* FROM fiscal_documents d LEFT JOIN fiscal_nfse_details nd ON nd.company_id=d.company_id AND nd.fiscal_document_id=d.id WHERE d.company_id=? AND d.model='NFSE' AND d.direction='SAIDA' AND ((d.source_type='PEDIDO' AND d.source_id=?) OR nd.pedido_id=?) ORDER BY (d.status='AUTORIZADA') DESC,d.id DESC LIMIT 1");$bs->execute([$companyId,(int)$invoice['pedido_id'],(int)$invoice['pedido_id']]);$batchNfseDoc=$bs->fetch(PDO::FETCH_ASSOC)?:null;}catch(Throwable $ignore){}
    }
    try{require_once __DIR__ . '/../config/gestao_module.php';$paymentMethods=gestao_payment_methods($pdo,$companyId,true);$paymentMethods=array_values(array_filter($paymentMethods,static fn(array $pm):bool=>strtoupper(trim((string)($pm['type']??'')))!=='VALE'&&strtoupper(trim((string)($pm['code']??'')))!=='VALE'));}catch(Throwable $e){if($error==='')$error=$e->getMessage();}
}

$today=date('Y-m-d');$periodStart=os_batch_date($_GET['period_start']??'')?:date('Y-m-01');$periodEnd=os_batch_date($_GET['period_end']??'')?:date('Y-m-t');if($periodEnd<$periodStart)[$periodStart,$periodEnd]=[$periodEnd,$periodStart];
$personId=max(0,(int)($_GET['person_id']??0));$personName='';if($personId>0){try{$st=$pdo->prepare('SELECT name FROM finance_people WHERE company_id=? AND id=? LIMIT 1');$st->execute([$companyId,$personId]);$personName=(string)$st->fetchColumn();}catch(Throwable $e){}}
$statusId=max(0,(int)($_GET['status_id']??0));
$invoiceSearch=((string)($_GET['invoice_search']??''))==='1';
$invoicePeriodStart=os_batch_date($_GET['invoice_period_start']??'')?:date('Y-m-01');
$invoicePeriodEnd=os_batch_date($_GET['invoice_period_end']??'')?:$today;if($invoicePeriodEnd<$invoicePeriodStart)[$invoicePeriodStart,$invoicePeriodEnd]=[$invoicePeriodEnd,$invoicePeriodStart];
$invoiceStatus=strtoupper(trim((string)($_GET['invoice_status']??'')));if(!in_array($invoiceStatus,['','CONFERENCIA','APROVADA','FATURADA','CANCELADA'],true))$invoiceStatus='';
$statuses=[];$candidates=[];$invoiceRows=[];
if($schemaOk){
    try{$st=$pdo->prepare('SELECT id,name,color,is_final FROM os_statuses WHERE company_id=? AND active=1 AND allow_batch_billing=1 ORDER BY sort_order,id');$st->execute([$companyId]);$statuses=$st->fetchAll(PDO::FETCH_ASSOC)?:[];}catch(Throwable $e){if($error==='')$error=$e->getMessage();}
    if(count($statuses)===1 && $statusId===0)$statusId=(int)$statuses[0]['id'];
    if($statusId>0 && !array_filter($statuses,static fn($s)=>(int)$s['id']===$statusId))$statusId=0;
}
if($schemaOk&&$invoiceId<=0){try{$candidates=os_batch_candidate_orders($pdo,$companyId,$personId,$statusId,$periodStart,$periodEnd);if($invoiceSearch)$invoiceRows=os_batch_list_invoices($pdo,$companyId,$invoicePeriodStart,$invoicePeriodEnd,0,$invoiceStatus);}catch(Throwable $e){if($error==='')$error=$e->getMessage();}}
$csrf=os_batch_csrf_token();

os_page_start('Faturamento em Lote de O.S.','faturas');
?>
<style>
