mportant;height:18px}.osbf-status{display:inline-flex;border-radius:999px;padding:5px 9px;font-size:12px;font-weight:900}.osbf-status.CONFERENCIA{background:#fff7ed;color:#9a3412}.osbf-status.APROVADA{background:#eff6ff;color:#1d4ed8}.osbf-status.FATURADA{background:#ecfdf5;color:#047857}.osbf-status.CANCELADA{background:#f1f5f9;color:#64748b}.osbf-toolbar{display:flex;gap:8px;align-items:center;justify-content:space-between;flex-wrap:wrap}.osbf-actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.osbf-muted{color:#64748b}.osbf-os-row{border-left:5px solid var(--os-color,#64748b);background:color-mix(in srgb,var(--os-color,#64748b) 5%,white)}.osbf-detail-grid{display:grid;grid-template-columns:1.25fr .75fr;gap:14px}.osbf-line{font-size:12px;color:#475569;margin-top:3px}.osbf-mobile{display:none}.osbf-modal{position:fixed;inset:0;background:rgba(15,23,42,.48);z-index:9999;display:none;align-items:flex-start;justify-content:center;padding:8vh 14px 20px}.osbf-modal.open{display:flex}.osbf-modal-card{width:min(760px,100%);background:#fff;border-radius:16px;box-shadow:0 22px 70px rgba(15,23,42,.25);overflow:hidden}.osbf-modal-head{display:flex;justify-content:space-between;align-items:center;padding:14px 16px;border-bottom:1px solid #cbd5e1}.osbf-modal-body{padding:14px}.osbf-search-row{display:flex;gap:8px}.osbf-search-list{margin-top:10px;border:1px solid #cbd5e1;border-radius:10px;max-height:360px;overflow:auto}.osbf-search-item{padding:10px 12px;border-bottom:1px solid #e2e8f0;cursor:pointer}.osbf-search-item:last-child{border-bottom:0}.osbf-search-item.active{background:#eaf2ff;outline:2px solid #93c5fd;outline-offset:-2px}.osbf-search-item strong{display:block;color:#0f172a}.osbf-search-item small{color:#64748b}.osbf-billing-box{border:1px solid #bfdbfe;background:#f8fbff;border-radius:14px;padding:14px}.osbf-warning{border:1px solid #fed7aa;background:#fff7ed;color:#9a3412;border-radius:12px;padding:11px 13px}.osbf-okbox{border:1px solid #a7f3d0;background:#ecfdf5;color:#065f46;border-radius:12px;padding:11px 13px}
