@media(max-width:560px){.osbf-filter{grid-template-columns:1fr}.osbf-history-filter{grid-template-columns:1fr}.osbf-history-filter .history-status,.osbf-history-filter .history-actions{grid-column:auto}.osbf-filter .person,.osbf-filter .status,.osbf-filter .actions{grid-column:auto}.osbf-summary{grid-template-columns:1fr 1fr}.osbf-mobile-grid{grid-template-columns:1fr}.osbf-actions .btn{flex:1 1 auto}.osbf-person{flex-direction:column}}
