<?php if($error!==''):?><div class="alert alert-error"><?=os_e($error)?></div><?php endif;?>
<?php if(!$schemaOk):?>
<div class="card"><div class="card-head">Instalação necessária</div><div class="card-body"><div class="alert alert-error">Execute <b>db/20260825_os_fiscal_status_faturado_v1.sql</b> no banco <b>nexaprospero</b> e recarregue esta tela.</div></div></div>
<?php elseif($invoice):?>
<div class="card"><div class="card-head osbf-toolbar"><span>Fatura de O.S. #<?=osbf_invoice_no($invoice['invoice_number'])?></span><span class="osbf-status <?=os_e($invoice['status'])?>"><?=os_e(os_batch_status_label((string)$invoice['status']))?></span></div><div class="card-body">
  <div class="osbf-detail-grid"><div><div class="grid"><div class="c6"><label>Cliente</label><strong><?=os_e($invoice['person_name_snapshot'])?></strong><div class="small muted"><?=os_e($invoice['person_document_snapshot'])?></div></div><div class="c3"><label>Período</label><strong><?=osbf_date_br($invoice['period_start'])?> a <?=osbf_date_br($invoice['period_end'])?></strong></div><div class="c3"><label>Emissão</label><strong><?=osbf_date_br($invoice['issue_date'])?></strong></div><?php if(!empty($invoice['status_filter_name'])):?><div class="c6"><label>Status usado no filtro</label><?=os_e($invoice['status_filter_name'])?></div><?php endif;?><?php if(trim((string)$invoice['notes'])!==''):?><div class="c12"><label>Observações</label><div><?=nl2br(os_e($invoice['notes']))?></div></div><?php endif;?></div></div>
  <div class="osbf-summary"><div><small>O.S.</small><strong><?=count($invoiceOrders)?></strong></div><div><small>Produtos</small><strong><?=os_money($invoice['total_products'])?></strong></div><div><small>Serviços</small><strong><?=os_money($invoice['total_services'])?></strong></div><div><small>Total</small><strong><?=os_money($invoice['total_general'])?></strong></div></div></div>
  <div class="osbf-actions" style="margin-top:14px"><a class="btn btn-primary" target="_blank" href="os_fatura_imprimir.php?id=<?=$invoiceId?>">Imprimir Fatura / Relação</a>
  <?php if($invoice['status']==='CONFERENCIA'):?><form method="post" onsubmit="return confirm('Confirma que o cliente conferiu e aprovou esta fatura?')"><input type="hidden" name="csrf" value="<?=os_e($csrf)?>"><input type="hidden" name="action" value="approve"><input type="hidden" name="invoice_id" value="<?=$invoiceId?>"><button class="btn btn-success">Marcar como aprovada</button></form><form method="post" onsubmit="return confirm('Cancelar esta fatura? As O.S. ficarão disponíveis para uma nova seleção.')"><input type="hidden" name="csrf" value="<?=os_e($csrf)?>"><input type="hidden" name="action" value="cancel"><input type="hidden" name="invoice_id" value="<?=$invoiceId?>"><button class="btn btn-danger">Cancelar</button></form><?php endif;?>
  <?php if($invoice['status']==='APROVADA'):?><form method="post"><input type="hidden" name="csrf" value="<?=os_e($csrf)?>"><input type="hidden" name="action" value="reopen"><input type="hidden" name="invoice_id" value="<?=$invoiceId?>"><button class="btn btn-secondary">Voltar para conferência</button></form><?php endif;?></div>
</div></div>

<div class="card"><div class="card-head">O.S. incluídas na fatura</div><div class="card-body"><div class="osbf-table-wrap"><table class="osbf-table"><thead><tr><th>O.S.</th><th>Data</th><th>Status</th><th>Descrição</th><th class="num">Produtos</th><th class="num">Serviços</th><th class="num">Total</th><th></th></tr></thead><tbody><?php foreach($invoiceOrders as $r):?><tr><td><strong>#<?=osbf_invoice_no($r['os_number_snapshot'])?></strong></td><td><?=osbf_date_br($r['service_date_snapshot'])?></td><td><?=os_e($r['status_name_snapshot'])?></td><td><?=os_e($r['title_snapshot']?:'—')?></td><td class="num"><?=os_money($r['total_products'])?></td><td class="num"><?=os_money($r['total_services'])?></td><td class="num"><strong><?=os_money($r['total_general'])?></strong></td><td><a class="btn btn-sm" href="os_editar.php?id=<?=(int)$r['os_order_id']?>">Abrir O.S.</a></td></tr><?php endforeach;?></tbody></table></div></div></div>

<?php if($invoice['status']==='APROVADA'):?>
<div class="card"><div class="card-head">Faturamento consolidado</div><div class="card-body"><div class="osbf-billing-box"><strong>Agora será criado um único Pedido e um único lançamento financeiro pelo total de <?=os_money($invoice['total_general'])?>.</strong><div class="small muted" style="margin-top:5px">Os itens continuam gravados com a O.S. de origem. Ao concluir, todas as O.S. serão alteradas para o status <b><?=os_e($billedStatus['name']??'Faturado não configurado')?></b>.</div></div><?php if(!$billedStatus):?><div class="alert alert-error" style="margin-top:12px"><b>Status Faturado não configurado.</b> Acesse Configurações → Configurações da O.S. → Status e marque um status como <b>Status Faturado</b> antes de concluir.</div><?php endif;?>
<form method="post" style="margin-top:14px" onsubmit="return confirm('Confirma o FATURAMENTO FINAL desta fatura? Será criado um Pedido consolidado e o financeiro pelo valor total.')"><input type="hidden" name="csrf" value="<?=os_e($csrf)?>"><input type="hidden" name="action" value="bill"><input type="hidden" name="invoice_id" value="<?=$invoiceId?>"><div class="grid"><div class="c6 osbf-field"><label>Forma de pagamento</label><select name="payment_method_id" id="osbfPayment" required><option value="">Selecione</option><?php foreach($paymentMethods as $pm):?><option value="<?=(int)$pm['id']?>" data-receivable="<?=!empty($pm['generate_receivable'])?'1':'0'?>"><?=os_e($pm['name'])?></option><?php endforeach;?></select></div><div class="c3 osbf-field"><label>Vencimento</label><input type="date" name="due_date" id="osbfDue" value="<?=os_e($creDueDefault)?>"></div><div class="c3" style="display:flex;align-items:end"><button class="btn btn-success" style="width:100%" <?=!$billedStatus?'disabled title="Configure o Status Faturado antes de concluir"':''?>>Faturar valor total</button></div></div></form></div></div>
<?php elseif($invoice['status']==='FATURADA'):?>
<div class="card"><div class="card-head">Faturamento concluído</div><div class="card-body"><div class="osbf-okbox"><strong>Fatura consolidada faturada.</strong><div style="margin-top:5px">Pedido consolidado: <b>#<?=os_e($pedidoDisplay)?></b><?php if($invoice['due_date']):?> · Vencimento: <b><?=osbf_date_br($invoice['due_date'])?></b><?php endif;?><?php if($billedStatus):?> · O.S. alteradas para: <b><?=os_e($billedStatus['name'])?></b><?php endif;?></div></div><div class="osbf-billing-box" style="margin-top:12px"><b>Documentos fiscais:</b> o Pedido consolidado agora usa o mesmo fluxo fiscal dos Pedidos gerados pelo PDV. As opções de NF-e, NFC-e e NFS-e serão exibidas conforme a composição do Pedido, permissões e configurações fiscais da empresa.</div><div class="osbf-actions" style="margin-top:12px"><a class="btn btn-primary" href="pedidos.php?q=<?=urlencode((string)$pedidoDisplay)?>">Abrir Pedido / Emitir documento fiscal</a><a class="btn btn-secondary" href="pedido_editar.php?id=<?=(int)$invoice['pedido_id']?>">Abrir Pedido</a><a class="btn btn-success" href="gestao_pedido_detalhado.php?os_nfse_lote=<?=$invoiceId?>">Conferir / emitir NFS-e</a></div>
<?php if($batchNfseDoc && strtoupper((string)$batchNfseDoc['status'])==='AUTORIZADA'):?><div class="osbf-actions" style="margin-top:8px"><a class="btn btn-outline" href="fiscal_nfse_imprimir.php?doc_id=<?=(int)$batchNfseDoc['id']?>" target="_blank">Imprimir NFS-e</a></div><?php endif;?>
