<div id="osbfPersonModal" class="osbf-modal"><div class="osbf-modal-card"><div class="osbf-modal-head"><strong>Buscar cliente</strong><button type="button" class="btn btn-secondary btn-sm" id="osbfClosePerson">Fechar</button></div><div class="osbf-modal-body"><div class="osbf-search-row"><input id="osbfPersonSearch" placeholder="Digite e pressione Enter" autocomplete="off"><button type="button" class="btn btn-primary" id="osbfRunPerson">Pesquisar</button></div><div class="small muted" style="margin-top:7px">Enter pesquisa; ↑/↓ percorrem os registros; Enter seleciona. Ao digitar novamente, Enter executa nova pesquisa.</div><div id="osbfPersonList" class="osbf-search-list"></div></div></div></div>
<script>
(function(){
  var modal=document.getElementById('osbfPersonModal'),btn=document.getElementById('osbfFindPerson'),close=document.getElementById('osbfClosePerson'),input=document.getElementById('osbfPersonSearch'),list=document.getElementById('osbfPersonList'),run=document.getElementById('osbfRunPerson'),pid=document.getElementById('osbfPersonId'),pname=document.getElementById('osbfPersonName');var rows=[],idx=-1,dirty=true;
  function open(){if(!modal)return;modal.classList.add('open');input.value='';list.innerHTML='';rows=[];idx=-1;dirty=true;setTimeout(function(){input.focus();},20)}function shut(){if(modal)modal.classList.remove('open')}
  function paint(){list.querySelectorAll('.osbf-search-item').forEach(function(el,i){el.classList.toggle('active',i===idx)});var a=list.querySelector('.active');if(a)a.scrollIntoView({block:'nearest'})}
  function select(i){var r=rows[i];if(!r)return;pid.value=r.id;pname.value=r.name||'';shut();var f=pid.closest('form');if(f)f.submit()}
  async function search(){dirty=false;idx=-1;list.innerHTML='<div class="osbf-search-item">Pesquisando...</div>';try{var res=await fetch('os_ajax.php?action=search_people&q='+encodeURIComponent(input.value||''),{credentials:'same-origin'}),j=await res.json();rows=(j&&j.ok&&Array.isArray(j.rows))?j.rows:[];list.innerHTML='';if(!rows.length){list.innerHTML='<div class="osbf-search-item">Nenhum cliente encontrado.</div>';return}rows.forEach(function(r,i){var d=document.createElement('div');d.className='osbf-search-item';d.tabIndex=0;d.innerHTML='<strong>'+esc(r.name||'')+'</strong><small>'+esc((r.document||'')+(r.whatsapp?' · '+r.whatsapp:''))+'</small>';d.addEventListener('click',function(){select(i)});list.appendChild(d)});idx=0;paint()}catch(e){list.innerHTML='<div class="osbf-search-item">Falha ao pesquisar.</div>'}}
  function esc(s){return String(s).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]})}
  if(btn)btn.addEventListener('click',open);if(close)close.addEventListener('click',shut);if(modal)modal.addEventListener('click',function(e){if(e.target===modal)shut()});if(run)run.addEventListener('click',search);if(input){input.addEventListener('input',function(){dirty=true});input.addEventListener('keydown',function(e){if(e.key==='ArrowDown'&&rows.length){e.preventDefault();idx=Math.min(rows.length-1,idx+1);paint()}else if(e.key==='ArrowUp'&&rows.length){e.preventDefault();idx=Math.max(0,idx-1);paint()}else if(e.key==='Enter'){e.preventDefault();if(!dirty&&rows.length&&idx>=0)select(idx);else search()}})}
  document.addEventListener('keydown',function(e){if(e.key!=='F8')return;var a=document.activeElement;if(a&&['INPUT','TEXTAREA','SELECT'].indexOf(a.tagName)>=0&&a!==pname)return;e.preventDefault();open()});
  var all=document.getElementById('osbfAll'),none=document.getElementById('osbfNone');function syncMobile(){document.querySelectorAll('.osbf-selector-mobile').forEach(function(m){var d=document.querySelector('.osbf-selector[value="'+m.dataset.order+'"]');if(d)m.checked=d.checked})}function setAll(v){document.querySelectorAll('.osbf-selector').forEach(function(c){c.checked=v});syncMobile()}if(all)all.addEventListener('click',function(){setAll(true)});if(none)none.addEventListener('click',function(){setAll(false)});document.querySelectorAll('.osbf-selector').forEach(function(c){c.addEventListener('change',syncMobile)});document.querySelectorAll('.osbf-selector-mobile').forEach(function(m){m.addEventListener('change',function(){var d=document.querySelector('.osbf-selector[value="'+m.dataset.order+'"]');if(d)d.checked=m.checked})});syncMobile();
})();
</script>
<?php os_page_end(); ?>
